Totales contar_tipos(const std::vector<Registro>& admitidos) {
    Totales total;
    for (const Registro& r : admitidos) {
        if (r.tipo == "textura") ++total.texturas;
        else if (r.tipo == "malla") ++total.mallas;
        else if (r.tipo == "sonido") ++total.sonidos;
        total.bytes += r.bytes;
    }
    return total;
}

